<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title><?= htmlspecialchars($title) ?> — <?= htmlspecialchars($brand['name']) ?></title><style>:root{--p:<?= htmlspecialchars($brand['primary']) ?>;--a:<?= htmlspecialchars($brand['accent']) ?>}*{box-sizing:border-box}body{margin:0;background:#e9efec;color:#183a35;font:13px Arial,sans-serif}.doc-tools{text-align:center;padding:18px}.doc-tools button,.doc-tools a{display:inline-flex;border:0;border-radius:8px;background:var(--p);color:#fff;padding:11px 17px;text-decoration:none;cursor:pointer;margin:3px;font-weight:700}.doc-page{width:210mm;min-height:297mm;margin:0 auto 30px;background:#fff;padding:18mm;box-shadow:0 22px 55px #183a3520;position:relative}.doc-head{display:flex;align-items:center;justify-content:space-between;border-bottom:3px solid var(--p);padding-bottom:15px}.doc-brand{display:flex;align-items:center;gap:10px}.doc-brand img{max-width:95px;max-height:55px}.doc-brand>span{width:48px;height:48px;border-radius:12px;display:grid;place-items:center;background:var(--p);color:#fff;font-weight:800}.doc-brand div{display:flex;flex-direction:column}.doc-brand strong{font-size:18px}.doc-brand small{font-size:8px;color:#70807b}.doc-ref{text-align:right;font-size:9px}.doc-ref strong{display:block;color:var(--p);font-size:12px}.doc-title{text-align:center;margin:38px 0}.doc-title small{color:var(--a);letter-spacing:3px;font-weight:800}.doc-title h1{font:800 30px Georgia;margin:10px}.doc-table{width:100%;border-collapse:collapse;margin:20px 0}.doc-table th{background:var(--p);color:#fff;padding:10px;text-align:left;font-size:9px}.doc-table td{border-bottom:1px solid #dfe5e2;padding:10px}.doc-summary{margin-left:auto;width:280px}.doc-summary p{display:flex;justify-content:space-between}.doc-summary .total{border-top:2px solid var(--p);padding-top:10px;font-size:16px}.doc-signatures{display:flex;justify-content:space-between;margin-top:70px;text-align:center}.doc-signatures div{width:210px;border-top:1px solid #71807c;padding-top:8px}.doc-foot{position:absolute;bottom:12mm;left:18mm;right:18mm;border-top:1px solid #dfe5e2;padding-top:8px;text-align:center;font-size:8px;color:#74827e}.identity-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:20px 0}.identity-grid div{background:#f3f6f4;padding:12px}.identity-grid small{display:block;color:#788680;font-size:8px}.identity-grid strong{display:block;margin-top:4px}.document-statement{text-align:center;font:18px/1.8 Georgia;margin:35px}.document-statement strong{font-size:25px;color:var(--p)}@page{size:A4 portrait;margin:0}@media print{body{background:#fff}.doc-tools{display:none}.doc-page{margin:0;box-shadow:none;min-height:297mm;print-color-adjust:exact;-webkit-print-color-adjust:exact}}@media(max-width:850px){.doc-page{transform-origin:top left;transform:scale(.65);margin-bottom:-100mm}}</style></head><body><?= $content ?></body></html>
